"use client";

import { useEffect, useState } from "react";

type View = "dashboard" | "planner" | "topics" | "study" | "journal" | "resources" | "exams" | "settings";
type TaskStatus = "planned" | "in_progress" | "done" | "partial" | "overdue" | "not_done" | "cancelled" | "rescheduled";
type StudyMode = "pomodoro" | "stopwatch" | "planned";
type Task = { id: string; title: string; subject: string; topic: string; day: string; start: string; duration: number; questions: number; doneQuestions: number; status: TaskStatus; priority: "low" | "medium" | "high"; color: string };
type Topic = { id: string; name: string; subject: string; exam: "TYT" | "AYT"; progress: number; confidence: number; questions: number; lastStudy: string; color: string };
type Resource = { id: string; title: string; type: string; subject: string; progress: number; total: string; accent: string };
type Journal = { id: string; date: string; title: string; text: string; mood: string; type: "Günlük" | "Haftalık" };
type RescheduleOption = { day: string; date: string; start: string; end: string; score: number; rationale: string; conflicts: string[] };

const weekDays = ["Pzt", "Sal", "Çar", "Per", "Cum", "Cmt", "Paz"];
const navItems: { id: View; label: string; icon: string }[] = [
  { id: "dashboard", label: "Genel Bakış", icon: "⌂" }, { id: "planner", label: "Planlayıcı", icon: "▦" }, { id: "topics", label: "Konular", icon: "◈" }, { id: "study", label: "Çalışma Alanı", icon: "◷" }, { id: "journal", label: "Günlük", icon: "✎" }, { id: "resources", label: "Kaynaklar", icon: "▤" }, { id: "exams", label: "Denemeler", icon: "⌁" },
];
const initialTasks: Task[] = [
  { id: "t1", title: "Problemler: Temel Kavramlar", subject: "TYT Matematik", topic: "Temel Kavramlar", day: "Pzt", start: "09:00", duration: 70, questions: 35, doneQuestions: 35, status: "done", priority: "high", color: "violet" },
  { id: "t2", title: "Paragraf hız seti", subject: "TYT Türkçe", topic: "Paragraf", day: "Pzt", start: "11:00", duration: 45, questions: 25, doneQuestions: 16, status: "partial", priority: "medium", color: "cyan" },
  { id: "t3", title: "Limit ve süreklilik", subject: "AYT Matematik", topic: "Limit", day: "Sal", start: "09:30", duration: 90, questions: 30, doneQuestions: 0, status: "planned", priority: "high", color: "pink" },
  { id: "t4", title: "Kuvvet ve hareket tekrar", subject: "AYT Fizik", topic: "Kuvvet ve Hareket", day: "Sal", start: "14:00", duration: 60, questions: 25, doneQuestions: 0, status: "planned", priority: "medium", color: "blue" },
  { id: "t5", title: "Organik kimya — alkoller", subject: "AYT Kimya", topic: "Organik Kimya", day: "Çar", start: "10:00", duration: 80, questions: 30, doneQuestions: 0, status: "planned", priority: "high", color: "orange" },
  { id: "t6", title: "Biyoloji konu özeti", subject: "AYT Biyoloji", topic: "Hücre", day: "Per", start: "09:00", duration: 50, questions: 20, doneQuestions: 0, status: "planned", priority: "low", color: "green" },
  { id: "t7", title: "TYT Fen mini deneme", subject: "TYT Fen", topic: "Karma", day: "Cmt", start: "13:30", duration: 60, questions: 40, doneQuestions: 0, status: "planned", priority: "medium", color: "amber" },
];
const initialTopics: Topic[] = [
  { id: "p1", name: "Temel Kavramlar", subject: "Matematik", exam: "TYT", progress: 78, confidence: 4, questions: 120, lastStudy: "Bugün", color: "violet" }, { id: "p2", name: "Paragraf", subject: "Türkçe", exam: "TYT", progress: 64, confidence: 3, questions: 80, lastStudy: "Dün", color: "cyan" }, { id: "p3", name: "Limit ve Süreklilik", subject: "Matematik", exam: "AYT", progress: 38, confidence: 2, questions: 30, lastStudy: "5 gün önce", color: "pink" }, { id: "p4", name: "Kuvvet ve Hareket", subject: "Fizik", exam: "AYT", progress: 52, confidence: 3, questions: 55, lastStudy: "3 gün önce", color: "blue" }, { id: "p5", name: "Organik Kimya", subject: "Kimya", exam: "AYT", progress: 21, confidence: 1, questions: 20, lastStudy: "1 hafta önce", color: "orange" }, { id: "p6", name: "Hücre", subject: "Biyoloji", exam: "AYT", progress: 69, confidence: 4, questions: 90, lastStudy: "2 gün önce", color: "green" },
];
const resources: Resource[] = [
  { id: "r1", title: "3D TYT Matematik", type: "Soru Bankası", subject: "TYT Matematik", progress: 68, total: "840 / 1.240 soru", accent: "violet" }, { id: "r2", title: "Bilgi Sarmal AYT Fizik", type: "Soru Bankası", subject: "AYT Fizik", progress: 42, total: "315 / 750 soru", accent: "cyan" }, { id: "r3", title: "Apotemi Limit", type: "Konu fasikülü", subject: "AYT Matematik", progress: 28, total: "9 / 32 test", accent: "pink" }, { id: "r4", title: "2025 Türkiye Geneli 4", type: "Deneme", subject: "TYT", progress: 100, total: "Tamamlandı", accent: "green" },
];
const initialJournals: Journal[] = [{ id: "j1", date: "17 Eylül 2026", title: "Daha sakin bir tempo", text: "Bugün problemler beklediğimden iyi gitti. Akşam limit için kısa bir tekrar yapacağım.", mood: "🌤️", type: "Günlük" }, { id: "j2", date: "Hafta 38", title: "İlk haftanın özeti", text: "Planın %82’sini tamamladım. Paragraf hızını biraz daha düzenli çalışmalıyım.", mood: "✨", type: "Haftalık" }];
const rescheduleOptions: RescheduleOption[] = [
  { day: "Çar", date: "18 Eyl", start: "09:00", end: "09:45", score: 92, rationale: "Sabah verimliliğin yüksek ve günün ilk bloğu boş.", conflicts: [] },
  { day: "Cmt", date: "21 Eyl", start: "11:00", end: "11:45", score: 84, rationale: "Hafta sonu boşluğuna sığıyor; dinlenme bloğunu koruyor.", conflicts: [] },
  { day: "Paz", date: "22 Eyl", start: "10:30", end: "11:15", score: 76, rationale: "Gecikmeyi azaltıyor; aynı dersten sonra kısa tekrar fırsatı sunuyor.", conflicts: ["12:00’de TYT Fen mini denemesi var"] },
];

const cx = (...values: (string | false | undefined)[]) => values.filter(Boolean).join(" ");

export default function Home() {
  const [view, setView] = useState<View>("dashboard"); const [tasks, setTasks] = useState<Task[]>(initialTasks); const [topics, setTopics] = useState<Topic[]>(initialTopics); const [journals, setJournals] = useState<Journal[]>(initialJournals); const [showTaskModal, setShowTaskModal] = useState(false); const [showQuickNote, setShowQuickNote] = useState(false); const [draggedTask, setDraggedTask] = useState<string | null>(null); const [rescheduleTaskId, setRescheduleTaskId] = useState<string | null>(null); const [query, setQuery] = useState(""); const [toast, setToast] = useState<string | null>(null); const [theme, setTheme] = useState<"light" | "dark">("dark"); const [activeExamTab, setActiveExamTab] = useState("Genel Bakış"); const [hydrated, setHydrated] = useState(false);
  // Local persistence hydrates after the first paint so the page remains SSR-safe.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { const saved = window.localStorage.getItem("yks-orbit-state"); if (saved) { try { const parsed = JSON.parse(saved); if (parsed.tasks) setTasks(parsed.tasks); if (parsed.topics) setTopics(parsed.topics); if (parsed.journals) setJournals(parsed.journals); if (parsed.theme === "light" || parsed.theme === "dark") setTheme(parsed.theme); } catch { /* stale state */ } } setHydrated(true); }, []);
  useEffect(() => { if (!hydrated) return; window.localStorage.setItem("yks-orbit-state", JSON.stringify({ version: 1, tasks, topics, journals, theme })); }, [hydrated, tasks, topics, journals, theme]);
  useEffect(() => { document.documentElement.dataset.theme = theme; }, [theme]);
  useEffect(() => { if ("serviceWorker" in navigator) navigator.serviceWorker.register("/sw.js").catch(() => undefined); }, []);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(null), 3000); return () => window.clearTimeout(timer); }, [toast]);
  const completedQuestions = tasks.reduce((sum, task) => sum + task.doneQuestions, 0); const plannedQuestions = tasks.reduce((sum, task) => sum + task.questions, 0); const completion = Math.round((completedQuestions / plannedQuestions) * 100); const todayTasks = tasks.filter((task) => task.day === "Sal");
  const moveTask = (id: string, day: string, start?: string) => { setTasks((current) => current.map((task) => task.id === id ? { ...task, day, ...(start ? { start } : {}), status: task.status === "done" ? "done" : "rescheduled" } : task)); setToast("Görev yeni güne taşındı · Plan güncellendi"); };
  const updateTaskStatus = (id: string, status: TaskStatus) => { setTasks((current) => current.map((task) => task.id === id ? { ...task, status, doneQuestions: status === "done" ? task.questions : task.doneQuestions } : task)); setToast(status === "done" ? "Görev tamamlandı · +10 XP" : "Görev durumu kaydedildi"); };
  const applyReschedule = (day: string, start: string) => { if (!rescheduleTaskId) return; moveTask(rescheduleTaskId, day, start); setRescheduleTaskId(null); };
  const exportData = () => { const payload = JSON.stringify({ exportedAt: new Date().toISOString(), version: 1, tasks, topics, journals }, null, 2); const url = URL.createObjectURL(new Blob([payload], { type: "application/json" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `yks-orbit-yedek-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); URL.revokeObjectURL(url); setToast("JSON yedeğin indirildi"); };
  const addTask = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const title = String(form.get("title") || "Yeni çalışma görevi"); const subject = String(form.get("subject") || "TYT Matematik"); const day = String(form.get("day") || "Sal"); const duration = Number(form.get("duration") || 60); const questions = Number(form.get("questions") || 30); setTasks((current) => [...current, { id: `task-${Date.now()}`, title, subject, topic: title, day, start: String(form.get("start") || "16:00"), duration, questions, doneQuestions: 0, status: "planned", priority: "medium", color: "cyan" }]); setShowTaskModal(false); setToast("Yeni görev plana eklendi"); };
  const addJournal = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const text = String(form.get("text") || ""); if (!text.trim()) return; setJournals((current) => [{ id: `journal-${Date.now()}`, date: "17 Eylül 2026", title: String(form.get("title") || "Bugünün notu"), text, mood: "✨", type: "Günlük" }, ...current]); setShowQuickNote(false); setToast("Günlük notun kaydedildi"); };
  return <div className="app-shell"><div className="ambient ambient-one" /><div className="ambient ambient-two" /><aside className="sidebar glass-panel"><div className="brand-row"><div className="brand-mark"><span>✦</span></div><div><strong>yks<span>orbit</span></strong><small>çalışma işletim sistemin</small></div></div><div className="profile-card"><div className="avatar">AY</div><div><strong>Arda Yılmaz</strong><span>2027 · Sayısal</span></div><button className="icon-button subtle" aria-label="Profil menüsü">•••</button></div><nav className="main-nav"><span className="nav-caption">ÇALIŞMA ALANI</span>{navItems.map((item) => <button key={item.id} onClick={() => setView(item.id)} className={cx("nav-item", view === item.id && "active")}><span className="nav-icon">{item.icon}</span><span>{item.label}</span>{item.id === "planner" && <em>3</em>}</button>)}<span className="nav-caption lower">SİSTEM</span><button onClick={() => setView("settings")} className={cx("nav-item", view === "settings" && "active")}><span className="nav-icon">⚙</span><span>Ayarlar</span></button></nav><div className="sidebar-bottom"><div className="streak-mini"><div className="streak-flame">♨</div><div><strong>12 gün</strong><span>Serin devam ediyor</span></div><span className="mini-arrow">→</span></div><button className="upgrade-card" onClick={() => setToast("Orbit Plus yakında seninle")}><span className="sparkle">✧</span><div><strong>Orbit Plus</strong><small>Daha derin içgörüler</small></div><span>›</span></button></div></aside><main className="main-content"><header className="topbar"><div className="breadcrumb"><span>Çalışma alanı</span><b>/</b><strong>{navItems.find((item) => item.id === view)?.label || "Ayarlar"}</strong></div><div className="top-actions"><label className="search-box"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ara..." /><kbd>⌘ K</kbd></label><button className="icon-button" onClick={() => setTheme(theme === "dark" ? "light" : "dark")} aria-label="Temayı değiştir">{theme === "dark" ? "☼" : "◐"}</button><button className="icon-button notification" onClick={() => setToast("Bugün 3 görevin ve 1 günlük hatırlatıcın var")} aria-label="Bildirimler">♢<i /></button><div className="top-avatar">AY</div></div></header>{view === "dashboard" && <Dashboard tasks={tasks} completion={completion} completedQuestions={completedQuestions} plannedQuestions={plannedQuestions} todayTasks={todayTasks} onNavigate={setView} onStart={() => setView("study")} onStatus={updateTaskStatus} onQuickNote={() => setShowQuickNote(true)} />}{view === "planner" && <Planner tasks={tasks} onAdd={() => setShowTaskModal(true)} onDragStart={setDraggedTask} onDrop={(day) => draggedTask && moveTask(draggedTask, day)} onStatus={updateTaskStatus} onReviewReschedule={setRescheduleTaskId} />}{view === "topics" && <Topics topics={topics.filter((topic) => `${topic.name} ${topic.subject}`.toLocaleLowerCase("tr").includes(query.toLocaleLowerCase("tr")))} setTopics={setTopics} onToast={setToast} />}{view === "study" && <Study tasks={tasks} onToast={setToast} onStatus={updateTaskStatus} />}{view === "journal" && <JournalView journals={journals} onAdd={() => setShowQuickNote(true)} />}{view === "resources" && <Resources onToast={setToast} />}{view === "exams" && <Exams activeTab={activeExamTab} setActiveTab={setActiveExamTab} onToast={setToast} />}{view === "settings" && <Settings theme={theme} setTheme={setTheme} onToast={setToast} onExport={exportData} />}</main>{showTaskModal && <TaskModal onClose={() => setShowTaskModal(false)} onSubmit={addTask} />}{showQuickNote && <QuickNoteModal onClose={() => setShowQuickNote(false)} onSubmit={addJournal} />}{rescheduleTaskId && <RescheduleModal task={tasks.find((task) => task.id === rescheduleTaskId)} onClose={() => setRescheduleTaskId(null)} onApply={applyReschedule} />}{toast && <div className="toast"><span>✓</span>{toast}</div>}</div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: React.ReactNode }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>; }
function Dashboard({ tasks, completion, completedQuestions, plannedQuestions, todayTasks, onNavigate, onStart, onStatus, onQuickNote }: { tasks: Task[]; completion: number; completedQuestions: number; plannedQuestions: number; todayTasks: Task[]; onNavigate: (view: View) => void; onStart: () => void; onStatus: (id: string, status: TaskStatus) => void; onQuickNote: () => void }) { const nextTask = todayTasks.find((task) => task.status !== "done") || todayTasks[0]; return <div className="content-scroll"><PageHeading eyebrow="PERŞEMBE, 17 EYLÜL 2026" title="Günaydın, Arda" description="Bugün küçük ama istikrarlı adımların günü. Hazırsan başlayalım." action={<div className="date-pill"><span>◷</span> 17 Eylül 2026 <b>⌄</b></div>} /><section className="hero-grid"><div className="hero-card glass-panel blue-gradient"><div className="hero-copy"><span className="eyebrow">BUGÜNÜN ODAĞI</span><h2>Bir sonraki doğru adım<br /><span>sadece 70 dakika uzakta.</span></h2><p>Programındaki en yüksek öncelikli görevi tamamla, günün geri kalanı kendiliğinden hafifleyecek.</p><button className="primary-button" onClick={onStart}>Çalışmayı başlat <span>→</span></button></div><div className="hero-orbit"><div className="orbit-ring ring-one" /><div className="orbit-ring ring-two" /><div className="orbit-core"><span>✦</span><strong>70</strong><small>dakika</small></div><div className="orbit-dot dot-one" /><div className="orbit-dot dot-two" /><div className="orbit-dot dot-three" /></div></div><div className="focus-card glass-panel"><div className="card-header"><div><span className="eyebrow">SIRADAKİ GÖREV</span><h3>{nextTask?.title || "Programın boş"}</h3></div><span className={cx("priority-dot", `priority-${nextTask?.priority || "medium"}`)} /></div><div className="focus-meta"><span>◷ {nextTask?.start || "--:--"}</span><span>◒ {nextTask?.duration || 0} dk</span><span>◈ {nextTask?.questions || 0} soru</span></div><div className="task-progress"><div className="progress-label"><span>Hazırlık</span><strong>{nextTask ? Math.round((nextTask.doneQuestions / Math.max(nextTask.questions, 1)) * 100) : 0}%</strong></div><div className="progress-track"><span style={{ width: `${nextTask ? Math.round((nextTask.doneQuestions / Math.max(nextTask.questions, 1)) * 100) : 0}%` }} /></div></div><button className="ghost-button full" onClick={onStart}>Görevi aç <span>↗</span></button></div></section><div className="stats-grid"><StatCard label="Haftalık ilerleme" value={`${completion}%`} change="+8.4%" helper="geçen haftaya göre" icon="◒" tone="violet" /><StatCard label="Çözülen soru" value={`${completedQuestions}`} change={`${plannedQuestions - completedQuestions}`} helper="soru kaldı" icon="◈" tone="cyan" /><StatCard label="Çalışma serisi" value="12 gün" change="En iyi: 18" helper="günlük hedefin açık" icon="♨" tone="orange" /><StatCard label="Konu hakimiyeti" value="%64" change="+3 konu" helper="bu hafta" icon="✦" tone="pink" /></div><section className="dashboard-grid"><div className="panel glass-panel weekly-panel"><div className="card-header"><div><span className="eyebrow">BU HAFTA</span><h3>Programın akışı</h3></div><button className="text-button" onClick={() => onNavigate("planner")}>Tümünü gör →</button></div><div className="week-strip">{weekDays.map((day, index) => <div className={cx("day-chip", index === 1 && "today")} key={day}><span>{day}</span><strong>{16 + index}</strong>{index === 1 && <i />}</div>)}</div><div className="mini-timeline">{tasks.filter((task) => task.day === "Sal").map((task) => <TaskRow key={task.id} task={task} onStatus={onStatus} />)}</div><button className="add-link" onClick={() => onNavigate("planner")}>+ Programa görev ekle</button></div><div className="panel glass-panel insight-panel"><div className="card-header"><div><span className="eyebrow">HAFTALIK İÇGÖRÜ</span><h3>Ritmin yükseliyor</h3></div><span className="insight-icon">✧</span></div><p>Son 7 günde en verimli olduğun zaman aralığı <strong>09:00 – 11:00</strong>. Zor konuları bu aralığa taşıyabilirsin.</p><div className="bar-chart"><div className="chart-y"><span>3s</span><span>2s</span><span>1s</span><span>0</span></div><div className="chart-bars">{[44, 72, 57, 86, 68, 96, 42].map((height, index) => <div className="bar-wrap" key={index}><div className={cx("bar", index === 3 && "highlight")} style={{ height: `${height}%` }} /><span>{weekDays[index]}</span></div>)}</div></div><div className="insight-foot"><span><i className="legend-dot violet" /> Planlanan</span><span><i className="legend-dot cyan" /> Gerçekleşen</span></div></div></section><section className="dashboard-grid lower-grid"><div className="panel glass-panel topics-panel"><div className="card-header"><div><span className="eyebrow">KONU RADARI</span><h3>Biraz daha ilgi isteyenler</h3></div><button className="icon-button subtle">•••</button></div>{initialTopics.slice(2, 5).map((topic) => <div className="topic-line" key={topic.id}><div className={cx("subject-badge", topic.color)}>{topic.subject.slice(0, 1)}</div><div className="topic-line-main"><div><strong>{topic.name}</strong><span>{topic.exam} {topic.subject}</span></div><div className="topic-line-progress"><div className="progress-track"><span className={topic.color} style={{ width: `${topic.progress}%` }} /></div><strong>{topic.progress}%</strong></div></div></div>)}<button className="add-link" onClick={() => onNavigate("topics")}>Tüm konu analizini aç →</button></div><div className="panel glass-panel journal-preview"><div className="card-header"><div><span className="eyebrow">GÜNLÜK</span><h3>Bugün nasıl gidiyor?</h3></div><span className="mood">🌤️</span></div><p>“Kendime daha az yüklenip daha çok devam ettiğim bir gün. Küçük ilerlemeler de ilerlemedir.”</p><button className="ghost-button full" onClick={onQuickNote}>Günlüğe not bırak <span>✎</span></button></div></section></div>; }
function StatCard({ label, value, change, helper, icon, tone }: { label: string; value: string; change: string; helper: string; icon: string; tone: string }) { return <div className="stat-card glass-panel"><div className={cx("stat-icon", tone)}>{icon}</div><span>{label}</span><strong>{value}</strong><div><b className={tone === "orange" ? "neutral-change" : "positive-change"}>{change}</b><small>{helper}</small></div></div>; }
function TaskRow({ task, onStatus }: { task: Task; onStatus: (id: string, status: TaskStatus) => void }) { const progress = Math.round((task.doneQuestions / task.questions) * 100); return <div className="task-row"><span className={cx("task-color", task.color)} /><div className="task-time">{task.start}<small>{task.duration} dk</small></div><div className="task-row-main"><strong>{task.title}</strong><span>{task.subject} · {task.questions} soru</span></div><div className="task-row-end"><div className="tiny-progress"><span style={{ width: `${progress}%` }} /></div><button className={cx("check-button", task.status === "done" && "checked")} onClick={() => onStatus(task.id, task.status === "done" ? "planned" : "done")}>{task.status === "done" ? "✓" : "○"}</button></div></div>; }

// Kept temporarily as a reference while the planner view is iterated.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function PlannerLegacy({ tasks, onAdd, onDragStart, onDrop, onStatus }: { tasks: Task[]; onAdd: () => void; onDragStart: (id: string) => void; onDrop: (day: string) => void; onStatus: (id: string, status: TaskStatus) => void }) { const [mode, setMode] = useState<"week" | "day">("week"); return <div className="content-scroll"><PageHeading eyebrow="PLANLAYICI" title="Haftanı senin ritmine göre kur." description="Sabit düzenini koru, yetişmeyenleri birlikte yeniden yerleştirelim." action={<button className="primary-button" onClick={onAdd}>+ Yeni görev</button>} /><div className="toolbar glass-panel"><div className="segmented"><button className={mode === "week" ? "selected" : ""} onClick={() => setMode("week")}>Hafta</button><button className={mode === "day" ? "selected" : ""} onClick={() => setMode("day")}>Gün</button></div><div className="toolbar-middle"><button className="icon-button subtle">‹</button><strong>16 – 22 Eylül 2026</strong><button className="icon-button subtle">›</button><button className="today-button">Bugün</button></div><div className="toolbar-actions"><button className="ghost-button">⌁ Filtrele</button><button className="ghost-button">☷ Görünüm</button></div></div><div className="calendar-scroll"><div className={cx("calendar-board glass-panel", mode === "day" && "day-mode")}><div className="calendar-corner"><span>GMT+03</span></div>{weekDays.map((day, index) => <div className={cx("calendar-day-head", index === 1 && "today")} key={day}><span>{day}</span><strong>{16 + index}</strong>{index === 1 && <i>bugün</i>}</div>)}<div className="time-column">{["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00"].map((time) => <span key={time}>{time}</span>)}</div>{weekDays.map((day) => <div className="calendar-column" key={day} onDragOver={(event) => event.preventDefault()} onDrop={() => onDrop(day)}>{[...Array(9)].map((_, row) => <div className="calendar-slot" key={row} />)}{tasks.filter((task) => task.day === day).map((task) => <div key={task.id} draggable onDragStart={() => onDragStart(task.id)} className={cx("calendar-task", task.color, task.status === "done" && "is-done")} style={{ top: `${(parseInt(task.start.split(":")[0], 10) - 8) * 58 + (parseInt(task.start.split(":")[1], 10) / 60) * 58}px`, height: `${Math.max(task.duration * 0.9, 42)}px` }}><div className="calendar-task-top"><strong>{task.start}</strong><button onClick={() => onStatus(task.id, task.status === "done" ? "planned" : "done")}>{task.status === "done" ? "✓" : "○"}</button></div><b>{task.title}</b><span>{task.questions} soru · {task.duration} dk</span></div>)}</div>)}</div></div><div className="planner-foot"><span><i className="legend-dot violet" /> Yüksek öncelik</span><span><i className="legend-dot cyan" /> Normal</span><span><i className="legend-dot muted" /> Dinlenme blokları korunuyor</span><span className="planner-hint">Görevi başka güne taşımak için sürükle bırak</span></div><div className="reschedule-card glass-panel"><div className="reschedule-symbol">↻</div><div><span className="eyebrow">AKILLI TELAFİ</span><h3>“Paragraf hız seti” için 3 uygun zaman bulduk.</h3><p>Bugünkü enerjini ve yarınki boşluğunu dikkate aldık. Önerileri incelemek ister misin?</p></div><button className="ghost-button" onClick={() => alert("Telafi önerileri: Cuma 09:00, Cumartesi 11:00, Pazar 10:30")}>Önerileri incele →</button></div></div>; }

function Planner({ tasks, onAdd, onDragStart, onDrop, onStatus, onReviewReschedule }: { tasks: Task[]; onAdd: () => void; onDragStart: (id: string) => void; onDrop: (day: string) => void; onStatus: (id: string, status: TaskStatus) => void; onReviewReschedule: (id: string) => void }) {
  const [mode, setMode] = useState<"week" | "day">("week");
  const pendingTask = tasks.find((task) => ["partial", "overdue", "not_done"].includes(task.status));
  const times = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00"];
  return <div className="content-scroll">
    <PageHeading eyebrow="PLANLAYICI" title="Haftanı senin ritmine göre kur." description="Sabit düzenini koru, yetişmeyenleri birlikte yeniden yerleştirelim." action={<button className="primary-button" onClick={onAdd}>+ Yeni görev</button>} />
    <div className="toolbar glass-panel"><div className="segmented"><button className={mode === "week" ? "selected" : ""} onClick={() => setMode("week")}>Hafta</button><button className={mode === "day" ? "selected" : ""} onClick={() => setMode("day")}>Gün</button></div><div className="toolbar-middle"><button className="icon-button subtle" aria-label="Önceki hafta">‹</button><strong>16 – 22 Eylül 2026</strong><button className="icon-button subtle" aria-label="Sonraki hafta">›</button><button className="today-button">Bugün</button></div><div className="toolbar-actions"><button className="ghost-button">⌁ Filtrele</button><button className="ghost-button">☷ Görünüm</button></div></div>
    <div className="calendar-scroll"><div className={cx("calendar-board glass-panel", mode === "day" && "day-mode")}><div className="calendar-corner"><span>GMT+03</span></div>{weekDays.map((day, index) => <div className={cx("calendar-day-head", index === 1 && "today")} key={day}><span>{day}</span><strong>{16 + index}</strong>{index === 1 && <i>bugün</i>}</div>)}<div className="time-column">{times.map((time) => <span key={time}>{time}</span>)}</div>{weekDays.map((day) => <div className="calendar-column" key={day} onDragOver={(event) => event.preventDefault()} onDrop={() => onDrop(day)}>{[...Array(9)].map((_, row) => <div className="calendar-slot" key={row} />)}{tasks.filter((task) => task.day === day).map((task) => <div key={task.id} draggable onDragStart={() => onDragStart(task.id)} className={cx("calendar-task", task.color, task.status === "done" && "is-done")} style={{ top: `${(parseInt(task.start.split(":")[0], 10) - 8) * 58 + (parseInt(task.start.split(":")[1], 10) / 60) * 58}px`, height: `${Math.max(task.duration * 0.9, 42)}px` }}><div className="calendar-task-top"><strong>{task.start}</strong><button aria-label={`${task.title} durumunu değiştir`} onClick={() => onStatus(task.id, task.status === "done" ? "planned" : "done")}>{task.status === "done" ? "✓" : "○"}</button></div><b>{task.title}</b><span>{task.questions} soru · {task.duration} dk</span></div>)}</div>)}</div></div>
    <div className="planner-foot"><span><i className="legend-dot violet" /> Yüksek öncelik</span><span><i className="legend-dot cyan" /> Normal</span><span><i className="legend-dot muted" /> Dinlenme blokları korunuyor</span><span className="planner-hint">Görevi başka güne taşımak için sürükle bırak</span></div>
    <div className="reschedule-card glass-panel"><div className="reschedule-symbol">↻</div><div><span className="eyebrow">AKILLI TELAFİ</span><h3>{pendingTask ? `“${pendingTask.title}” için 3 uygun zaman bulduk.` : "Telafi bekleyen görev yok."}</h3><p>{pendingTask ? "Bugünkü enerjini ve boşluklarını dikkate aldık. Önerilerden birini seçmeden hiçbir görev taşınmaz." : "Bir görev yetişmediğinde, çakışmaları koruyarak burada seçenekler göstereceğiz."}</p></div><button className="ghost-button" disabled={!pendingTask} onClick={() => pendingTask && onReviewReschedule(pendingTask.id)}>Önerileri incele →</button></div>
  </div>;
}

function Topics({ topics, setTopics, onToast }: { topics: Topic[]; setTopics: React.Dispatch<React.SetStateAction<Topic[]>>; onToast: (message: string) => void }) { const [tab, setTab] = useState<"Tümü" | "TYT" | "AYT">("Tümü"); const visible = topics.filter((topic) => tab === "Tümü" || topic.exam === tab); return <div className="content-scroll"><PageHeading eyebrow="KONU KÜTÜPHANESİ" title="Nerede olduğunu bil, sıradaki adımı gör." description="Resmî müfredat temeli üzerinde kendi konu ağacını oluştur." action={<button className="primary-button" onClick={() => { const name = window.prompt("Yeni konu adı"); if (name) { setTopics((current) => [...current, { id: `topic-${Date.now()}`, name, subject: "Kişisel", exam: "TYT", progress: 0, confidence: 1, questions: 0, lastStudy: "Henüz çalışılmadı", color: "cyan" }]); onToast("Yeni konu eklendi"); } }}>+ Konu ekle</button>} /><div className="topic-summary-grid"><div className="topic-summary glass-panel"><span className="eyebrow">TOPLAM KONU</span><strong>142</strong><p><b>38</b> konu tamamlandı</p><div className="summary-ring"><div><strong>27%</strong><span>genel</span></div></div></div><div className="topic-summary glass-panel"><span className="eyebrow">BU HAFTA</span><strong>11</strong><p>konu üzerinde çalıştın</p><div className="spark-bars">{[36, 54, 42, 68, 55, 75, 82].map((height, index) => <span key={index} style={{ height: `${height}%` }} />)}</div></div><div className="topic-summary glass-panel"><span className="eyebrow">TEKRAR BEKLEYEN</span><strong>8</strong><p>konu ilgini bekliyor</p><div className="topic-summary-list"><span><i className="legend-dot pink" /> Limit ve süreklilik</span><span><i className="legend-dot orange" /> Organik kimya</span></div></div></div><div className="section-toolbar"><div className="segmented"><button className={tab === "Tümü" ? "selected" : ""} onClick={() => setTab("Tümü")}>Tümü <small>142</small></button><button className={tab === "TYT" ? "selected" : ""} onClick={() => setTab("TYT")}>TYT <small>86</small></button><button className={tab === "AYT" ? "selected" : ""} onClick={() => setTab("AYT")}>AYT <small>56</small></button></div><div className="view-toggle"><button className="selected">▦</button><button>☷</button></div></div><div className="topic-grid">{visible.map((topic) => <div className="topic-card glass-panel" key={topic.id}><div className="topic-card-head"><div className={cx("subject-badge large", topic.color)}>{topic.subject.slice(0, 1)}</div><div><span className="exam-chip">{topic.exam}</span><h3>{topic.name}</h3><p>{topic.subject}</p></div><button className="icon-button subtle">•••</button></div><div className="topic-progress-line"><div className="progress-track"><span className={topic.color} style={{ width: `${topic.progress}%` }} /></div><strong>{topic.progress}%</strong></div><div className="topic-card-meta"><span>◒ Son çalışma: {topic.lastStudy}</span><span>◈ {topic.questions} soru</span></div><div className="confidence"><span>Hakimiyet</span><div>{[1, 2, 3, 4, 5].map((dot) => <i className={dot <= topic.confidence ? "filled" : ""} key={dot} />)}</div></div></div>)}</div></div>; }

function Study({ tasks, onToast, onStatus }: { tasks: Task[]; onToast: (message: string) => void; onStatus: (id: string, status: TaskStatus) => void }) { const [mode, setMode] = useState<StudyMode>("pomodoro"); const [seconds, setSeconds] = useState(25 * 60); const [running, setRunning] = useState(false); const [selectedTask, setSelectedTask] = useState(tasks.find((task) => task.status !== "done")?.id || tasks[0].id); const selected = tasks.find((task) => task.id === selectedTask); useEffect(() => { if (!running) return; const timer = window.setInterval(() => setSeconds((current) => { if (current <= 1) { window.clearInterval(timer); setRunning(false); onToast("Seans tamamlandı · Mola zamanı"); return 0; } return current - 1; }), 1000); return () => window.clearInterval(timer); }, [running, onToast]); const mins = String(Math.floor(seconds / 60)).padStart(2, "0"); const secs = String(seconds % 60).padStart(2, "0"); const selectMode = (next: StudyMode) => { setMode(next); setRunning(false); setSeconds(next === "pomodoro" ? 25 * 60 : next === "planned" ? (selected?.duration || 60) * 60 : 0); }; return <div className="content-scroll"><PageHeading eyebrow="ÇALIŞMA ALANI" title="Odaklanmak için alanını aç." description="Programdaki bir görevi seç veya bugün neye ihtiyacın varsa onunla başla." action={<div className="live-pill"><i /> Sistem hazır</div>} /><div className="study-layout"><div className="timer-panel glass-panel"><div className="timer-tabs">{([['pomodoro', 'Pomodoro'], ['stopwatch', 'Kronometre'], ['planned', 'Planlı seans']] as [StudyMode, string][]).map(([key, label]) => <button className={mode === key ? "selected" : ""} key={key} onClick={() => selectMode(key)}>{label}</button>)}</div><div className="timer-circle"><div className="timer-progress" style={{ transform: `rotate(${mode === "stopwatch" ? 0 : Math.max(0, 360 - (seconds / ((mode === "pomodoro" ? 25 : selected?.duration || 60) * 60)) * 360)}deg)` }} /><div className="timer-center"><span>{mode === "pomodoro" ? "ODAK" : mode === "planned" ? "PLANLI" : "SERBEST"}</span><strong>{mode === "stopwatch" && seconds === 0 ? "00:00" : `${mins}:${secs}`}</strong><small>{running ? "Devam ediyor" : "Başlamaya hazır"}</small></div></div><div className="timer-controls"><button className="round-control" onClick={() => setSeconds(mode === "pomodoro" ? 25 * 60 : (selected?.duration || 60) * 60)}>↺</button><button className="play-control" onClick={() => setRunning((current) => !current)}>{running ? "Ⅱ" : "▶"}</button><button className="round-control" onClick={() => setSeconds((current) => current + 5 * 60)}>＋</button></div><div className="timer-caption"><span>Bugünün odağı</span><strong>{selected?.title}</strong><small>{selected?.subject} · {selected?.questions} soru</small></div></div><div className="study-side"><div className="study-task-picker glass-panel"><div className="card-header"><div><span className="eyebrow">ÇALIŞILACAK GÖREV</span><h3>Bugünden seç</h3></div><button className="text-button">Değiştir</button></div>{tasks.slice(0, 4).map((task) => <button key={task.id} className={cx("study-task-option", selectedTask === task.id && "selected")} onClick={() => { setSelectedTask(task.id); if (mode === "planned") setSeconds(task.duration * 60); }}><span className={cx("task-color", task.color)} /><div><strong>{task.title}</strong><small>{task.start} · {task.duration} dk · {task.questions} soru</small></div><span className="option-check">{selectedTask === task.id ? "✓" : "○"}</span></button>)}</div><div className="session-log glass-panel"><div className="card-header"><div><span className="eyebrow">SON SEANSLAR</span><h3>Bugünün ritmi</h3></div><span className="session-total">2s 10dk</span></div><div className="session-item"><span className="session-icon violet">◒</span><div><strong>Problemler: Temel Kavramlar</strong><small>09:04 · 70 dakika · 35 soru</small></div><b>+10 XP</b></div><div className="session-item"><span className="session-icon cyan">◒</span><div><strong>Paragraf hız seti</strong><small>11:12 · 28 dakika · 16 soru</small></div><b>+5 XP</b></div><button className="add-link">Tüm çalışma geçmişi →</button></div></div></div>{selected && selected.status !== "done" && <div className="session-complete glass-panel"><div><span className="eyebrow">SEANS BİTİNCE</span><h3>İşaretlemeyi unutma</h3><p>Çözdüğün soru sayısını kaydettiğinde konu radarın da güncellenir.</p></div><button className="ghost-button" onClick={() => onStatus(selected.id, "done")}>Tamamlandı olarak işaretle ✓</button></div>}</div>; }

function JournalView({ journals, onAdd }: { journals: Journal[]; onAdd: () => void }) { return <div className="content-scroll"><PageHeading eyebrow="GÜNLÜK & YANSIMA" title="Kendine de yer aç." description="Ne yaptığını, ne hissettiğini ve sıradaki niyetini kaydet." action={<button className="primary-button" onClick={onAdd}>+ Günlük notu</button>} /><div className="journal-layout"><div className="journal-calendar glass-panel"><div className="card-header"><div><span className="eyebrow">EYLÜL 2026</span><h3>Takvim</h3></div><div className="month-nav"><button>‹</button><button>›</button></div></div><div className="calendar-weekdays">{["P", "S", "Ç", "P", "C", "C", "P"].map((day, index) => <span key={index}>{day}</span>)}</div><div className="calendar-days">{[...Array(30)].map((_, index) => <button className={cx(index === 16 && "selected", [1, 3, 5, 8, 10, 12, 14, 16, 17, 20, 22, 24, 26].includes(index) && "has-note")} key={index}>{index + 1}</button>)}</div><div className="journal-calendar-legend"><span><i className="legend-dot cyan" /> Günlük</span><span><i className="legend-dot violet" /> Haftalık</span></div></div><div className="journal-feed"><div className="feed-heading"><div><span className="eyebrow">SON KAYITLAR</span><h2>17 Eylül, Perşembe</h2></div><div className="mood-selector">🌤️ <span>İyi gidiyor</span>⌄</div></div>{journals.map((journal) => <article className="journal-entry glass-panel" key={journal.id}><div className="entry-top"><span className={cx("entry-type", journal.type === "Haftalık" && "weekly")}>{journal.type}</span><time>{journal.date}</time><span className="entry-mood">{journal.mood}</span></div><h3>{journal.title}</h3><p>{journal.text}</p><div className="entry-foot"><span>✦ Son güncelleme bugün</span><button className="text-button">Düzenle →</button></div></article>)}<button className="journal-empty" onClick={onAdd}><span>＋</span><div><strong>Bugüne bir şey ekle</strong><small>Bir cümle bile yeter.</small></div></button></div></div></div>; }

function Resources({ onToast }: { onToast: (message: string) => void }) { return <div className="content-scroll"><PageHeading eyebrow="KAYNAK KÜTÜPHANESİ" title="Elindeki gücü görünür kıl." description="Kitaplarını, fasiküllerini ve denemelerini konularla eşleştir." action={<button className="primary-button" onClick={() => onToast("Kaynak ekleme formu açılacak")}>+ Kaynak ekle</button>} /><div className="resource-summary"><div className="resource-summary-main glass-panel"><div><span className="eyebrow">TOPLAM İLERLEME</span><strong>%57</strong><p>4 aktif kaynak · 1.475 soru çözüldü</p></div><div className="resource-donut"><div><strong>57</strong><span>%</span></div></div></div><div className="resource-stat glass-panel"><span className="stat-icon cyan">◈</span><div><span>Bu ay çözülen</span><strong>486 soru</strong><small>geçen aya göre <b>+18%</b></small></div></div><div className="resource-stat glass-panel"><span className="stat-icon pink">⌁</span><div><span>Aktif kaynak</span><strong>4 kaynak</strong><small>2 tanesi bitmeye yakın</small></div></div></div><div className="section-toolbar"><div><span className="eyebrow">KAYNAKLARIN</span><h2>İlerleme durumu</h2></div><div className="toolbar-actions"><button className="ghost-button">⌁ Filtrele</button><button className="ghost-button">↕ Sırala</button></div></div><div className="resource-grid">{resources.map((resource) => <article className="resource-card glass-panel" key={resource.id}><div className={cx("resource-cover", resource.accent)}><span>◈</span><small>{resource.type}</small><strong>{resource.title.split(" ").slice(0, 2).join(" ")}</strong></div><div className="resource-body"><div className="resource-title"><div><h3>{resource.title}</h3><span>{resource.subject}</span></div><button className="icon-button subtle">•••</button></div><div className="resource-progress"><div className="progress-label"><span>İlerleme</span><strong>{resource.progress}%</strong></div><div className="progress-track"><span className={resource.accent} style={{ width: `${resource.progress}%` }} /></div></div><div className="resource-foot"><span>{resource.total}</span><button className="text-button">Detay →</button></div></div></article>)}</div></div>; }

function Exams({ activeTab, setActiveTab, onToast }: { activeTab: string; setActiveTab: (tab: string) => void; onToast: (message: string) => void }) { return <div className="content-scroll"><PageHeading eyebrow="DENEME MERKEZİ" title="Çizgiyi değil, yönü takip et." description="Sonuçların sana nerede olduğunu ve nereye gideceğini söylesin." action={<button className="primary-button" onClick={() => onToast("Yeni deneme formu açılacak")}>+ Deneme ekle</button>} /><div className="exam-hero glass-panel"><div><span className="eyebrow">HEDEFİN</span><h2>İstanbul Teknik Üniversitesi<br /><span>Bilgisayar Mühendisliği</span></h2><div className="target-meta"><span>Hedef sıralama <strong>12.500</strong></span><span>Hedef puan <strong>495,2</strong></span><span>YKS 2027 <strong>♧ 275 gün</strong></span></div></div><div className="target-progress"><div className="target-ring"><div><strong>68%</strong><span>hedefe<br />yakınlık</span></div></div><button className="text-button">Hedefi düzenle →</button></div></div><div className="exam-tabs">{["Genel Bakış", "Netler", "Denemeler", "Hedefler"].map((tab) => <button className={activeTab === tab ? "selected" : ""} onClick={() => setActiveTab(tab)} key={tab}>{tab}</button>)}</div><div className="exam-grid"><div className="panel glass-panel score-panel"><div className="card-header"><div><span className="eyebrow">NET TRENDİ</span><h3>Son 6 deneme</h3></div><span className="trend-pill">↗ +8,4 net</span></div><div className="line-chart"><svg viewBox="0 0 560 190" role="img" aria-label="Net trend grafiği"><defs><linearGradient id="lineFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#8b7cff" stopOpacity=".32" /><stop offset="1" stopColor="#8b7cff" stopOpacity="0" /></linearGradient></defs><path d="M0 160 C65 142, 75 136, 110 146 S160 122, 205 129 S250 96, 300 112 S350 85, 395 94 S450 48, 500 64 S540 34, 560 42 V190 H0Z" fill="url(#lineFill)" /><path d="M0 160 C65 142, 75 136, 110 146 S160 122, 205 129 S250 96, 300 112 S350 85, 395 94 S450 48, 500 64 S540 34, 560 42" fill="none" stroke="#a79bff" strokeWidth="3" /><circle cx="450" cy="48" r="5" fill="#fff" stroke="#a79bff" strokeWidth="3" /></svg><div className="line-labels"><span>1. deneme</span><span>2.</span><span>3.</span><span>4.</span><span>5.</span><span>6. deneme</span></div></div></div><div className="panel glass-panel latest-exams"><div className="card-header"><div><span className="eyebrow">SON DENEMELER</span><h3>Sonuçlar</h3></div><button className="text-button">Tümü →</button></div>{[{ name: "Türkiye Geneli 4", date: "15 Eyl", net: "92,5", change: "+3,5" }, { name: "Karekök TYT 2", date: "09 Eyl", net: "89", change: "+1,25" }, { name: "Özdebir AYT 1", date: "02 Eyl", net: "47,75", change: "−2,5" }].map((exam) => <div className="latest-exam" key={exam.name}><span className="exam-number">{exam.name.slice(-1)}</span><div><strong>{exam.name}</strong><small>{exam.date} · TYT</small></div><div className="exam-score"><strong>{exam.net}</strong><span className={exam.change.startsWith("−") ? "negative" : "positive"}>{exam.change}</span></div></div>)}</div></div><div className="weakness-banner glass-panel"><span>✦</span><div><strong>Son denemenden bir içgörü</strong><p>Limit ve süreklilikteki yanlışların toplam yanlışlarının %24’ünü oluşturuyor. Bu hafta için 2 kısa tekrar önerdik.</p></div><button className="ghost-button" onClick={() => onToast("2 öneri planına eklendi")}>Önerileri plana ekle</button></div></div>; }

function Settings({ theme, setTheme, onToast, onExport }: { theme: "light" | "dark"; setTheme: (theme: "light" | "dark") => void; onToast: (message: string) => void; onExport: () => void }) { return <div className="content-scroll"><PageHeading eyebrow="AYARLAR" title="Sistemi kendine göre ayarla." description="Çalışma ritmin, görünümün ve verilerin üzerinde kontrol sende." /><div className="settings-layout"><aside className="settings-nav glass-panel">{["Profil ve hedef", "Planlayıcı", "Bildirimler", "Görünüm", "AI özellikleri", "Veri ve gizlilik"].map((item, index) => <button className={index === 0 ? "selected" : ""} key={item}><span>{["♙", "▦", "♢", "◐", "✧", "◈"][index]}</span>{item}<b>›</b></button>)}</aside><div className="settings-main"><div className="settings-section glass-panel"><div className="settings-section-heading"><div><span className="eyebrow">PROFİL VE HEDEF</span><h2>Yolculuğunun ayarları</h2></div><span className="saved-pill">✓ Kaydedildi</span></div><div className="settings-profile"><div className="avatar large">AY</div><div><h3>Arda Yılmaz</h3><p>arda@example.com</p><button className="text-button">Profil fotoğrafını değiştir</button></div></div><div className="form-grid"><label>Hedef sınav<select defaultValue="2027 YKS"><option>2027 YKS</option><option>2028 YKS</option></select></label><label>Alan<select defaultValue="Sayısal"><option>Sayısal</option><option>Eşit Ağırlık</option><option>Sözel</option></select></label><label className="wide">Hedef bölüm<input defaultValue="İTÜ · Bilgisayar Mühendisliği" /></label></div></div><div className="settings-section glass-panel"><div className="settings-section-heading"><div><span className="eyebrow">GÖRÜNÜM</span><h2>Arayüz tercihleri</h2></div></div><div className="setting-row"><div><strong>Tema</strong><span>Açık veya koyu görünüm arasında geçiş yap.</span></div><div className="theme-toggle"><button className={theme === "light" ? "selected" : ""} onClick={() => setTheme("light")}>☼ Açık</button><button className={theme === "dark" ? "selected" : ""} onClick={() => setTheme("dark")}>◐ Koyu</button></div></div><div className="setting-row"><div><strong>Hareketleri azalt</strong><span>Animasyonları ve geçişleri daha sakin yap.</span></div><button className="switch" onClick={() => onToast("Hareket ayarı güncellendi")}><i /></button></div></div><div className="settings-section glass-panel"><div className="settings-section-heading"><div><span className="eyebrow">VERİ VE GİZLİLİK</span><h2>Verilerin senin</h2></div></div><div className="privacy-row"><span className="privacy-icon">♢</span><div><strong>Yerel yedekleme</strong><p>Planlarını JSON veya CSV olarak indir.</p></div><button className="ghost-button" onClick={onExport}>Dışa aktar</button></div><div className="privacy-row"><span className="privacy-icon">✧</span><div><strong>AI anahtarı</strong><p>İsteğe bağlı. Anahtarın cihazında şifreli tutulur.</p></div><button className="ghost-button" onClick={() => onToast("AI ayarları yakında")}>Yapılandır</button></div></div></div></div></div>; }

function TaskModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) { return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="modal glass-panel"><div className="modal-header"><div><span className="eyebrow">YENİ GÖREV</span><h2>Planına ne ekleyelim?</h2></div><button className="icon-button" onClick={onClose}>×</button></div><form onSubmit={onSubmit}><label>Görev adı<input name="title" placeholder="Örn. Limit testleri" autoFocus required /></label><div className="form-grid"><label>Ders<select name="subject" defaultValue="AYT Matematik"><option>TYT Matematik</option><option>TYT Türkçe</option><option>AYT Matematik</option><option>AYT Fizik</option><option>AYT Kimya</option><option>AYT Biyoloji</option></select></label><label>Gün<select name="day" defaultValue="Sal">{weekDays.map((day) => <option key={day}>{day}</option>)}</select></label><label>Başlangıç<input name="start" type="time" defaultValue="16:00" /></label><label>Süre (dk)<input name="duration" type="number" defaultValue="60" min="5" /></label><label className="wide">Hedef soru<input name="questions" type="number" defaultValue="30" min="1" /></label></div><label>Not <textarea name="note" placeholder="Bu oturum için küçük bir niyet..." /></label><div className="modal-actions"><button type="button" className="ghost-button" onClick={onClose}>Vazgeç</button><button className="primary-button" type="submit">Göreve ekle <span>→</span></button></div></form></div></div>; }
function QuickNoteModal({ onClose, onSubmit }: { onClose: () => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) { return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="modal glass-panel note-modal"><div className="modal-header"><div><span className="eyebrow">17 EYLÜL 2026 · GÜNLÜK</span><h2>Bugün nasıl geçti?</h2></div><button className="icon-button" onClick={onClose}>×</button></div><form onSubmit={onSubmit}><label>Başlık<input name="title" defaultValue="Bugünün notu" /></label><label>Notun<textarea name="text" autoFocus placeholder="Aklından geçenleri, yaptıklarını veya yarınki niyetini yaz..." required /></label><div className="prompt-chips"><button type="button">Bugün neyi iyi yaptım?</button><button type="button">Yarın neye odaklanacağım?</button></div><div className="modal-actions"><button type="button" className="ghost-button" onClick={onClose}>Vazgeç</button><button className="primary-button" type="submit">Notu kaydet <span>✦</span></button></div></form></div></div>; }

function RescheduleModal({ task, onClose, onApply }: { task?: Task; onClose: () => void; onApply: (day: string, start: string) => void }) {
  const [selectedIndex, setSelectedIndex] = useState(0);
  if (!task) return null;
  const selected = rescheduleOptions[selectedIndex];
  return <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="modal glass-panel reschedule-modal"><div className="modal-header"><div><span className="eyebrow">AKILLI TELAFİ · ONAYIN GEREKİYOR</span><h2>{task.title}</h2><p className="modal-subtitle">Görevi taşımadan önce en uygun zamanı seç.</p></div><button className="icon-button" onClick={onClose} aria-label="Telafi penceresini kapat">×</button></div><div className="reschedule-reason"><span className="reason-dot">!</span><div><strong>Bu görev kısmen tamamlandı.</strong><p>{task.doneQuestions} / {task.questions} soru tamamlandı. Kalan kısmı seçtiğin zamana taşıyacağız.</p></div></div><div className="reschedule-options">{rescheduleOptions.map((option, index) => <button type="button" key={`${option.day}-${option.start}`} className={cx("reschedule-option", selectedIndex === index && "selected")} onClick={() => setSelectedIndex(index)}><span className="option-radio">{selectedIndex === index ? "✓" : "○"}</span><span className="option-date"><strong>{option.day}</strong><small>{option.date}</small></span><span className="option-time"><strong>{option.start} – {option.end}</strong><small>{option.score} uyum puanı</small></span><span className="option-score">{index === 0 ? "En iyi" : index === 1 ? "Dengeli" : "Alternatif"}</span></button>)}</div><div className="reschedule-rationale"><span>✦</span><p>{selected.rationale}{selected.conflicts.length > 0 && <><br /><small>Not: {selected.conflicts.join(" · ")}</small></>}</p></div><div className="modal-actions"><button type="button" className="ghost-button" onClick={onClose}>Şimdilik taşıma</button><button type="button" className="primary-button" onClick={() => onApply(selected.day, selected.start)}>Bu zamanı onayla <span>→</span></button></div></div></div>;
}
